		/**
		 * Returns a new populated Subscriber
		 * 
		 * @return Subscriber
		 */
		protected Subscriber generateNewEntity() {
			Subscriber entity = new Subscriber( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new HashSet<>(),  NotificationChannel.values()[0] );
			
			return( entity );
		}

